# -*- coding: utf-8 -*-
"""Build the profile README visuals.

One spec, two themes. Every visual is written to assets/<name>.svg (light) and
assets/dark/<name>.svg, so the README can serve them through <picture> and
prefers-color-scheme without depending on any widget service.

What is NOT built here, on purpose:
  * the project recap  -> a markdown table in README.md, so the rows are real
    links and stay readable when the image is scaled down;
  * the stack grid     -> devicon <img> tags in README.md;
  * the contribution snake -> generated by .github/workflows/snake.yml into the
    `output` branch.

Run:  python tools/build.py
"""

from __future__ import annotations

import os
from xml.sax.saxutils import escape

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
W = 846  # GitHub's README column on desktop

# Backgrounds stay transparent so the visuals sit on whatever GitHub theme the
# reader uses, including the dimmed one. Only ink colours differ per theme.
THEMES = {
    "light": dict(ink="#1f2328", muted="#59636e", line="#d1d9e0",
                  accent="#8a5a00", wash="#f6f8fa", band="#eaeef2",
                  mark="#241206", markfg="#fbefd8"),
    "dark": dict(ink="#e6edf3", muted="#9198a1", line="#3d444d",
                 accent="#d9a441", wash="#161b22", band="#21262d",
                 mark="#fbefd8", markfg="#241206"),
}

MONO = "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace"
SANS = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif"


# ---------------------------------------------------------------- primitives

def svg(height: int, body: str) -> str:
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{height}" '
        f'viewBox="0 0 {W} {height}" role="img">\n{body}</svg>\n'
    )


def text(x, y, s, *, size=24, fill="ink", font=SANS, weight=400,
         anchor="start", spacing=0, t=None) -> str:
    a = [f'x="{x}"', f'y="{y}"', f'font-family="{font}"', f'font-size="{size}"',
         f'font-weight="{weight}"', f'fill="{t[fill] if fill in t else fill}"']
    if anchor != "start":
        a.append(f'text-anchor="{anchor}"')
    if spacing:
        a.append(f'letter-spacing="{spacing}"')
    return f'  <text {" ".join(a)}>{escape(s)}</text>\n'


def rule(x1, y, x2, t, *, stroke="line", width=1, dash=None) -> str:
    d = f' stroke-dasharray="{dash}"' if dash else ""
    return (f'  <line x1="{x1}" y1="{y}" x2="{x2}" y2="{y}" '
            f'stroke="{t[stroke]}" stroke-width="{width}"{d}/>\n')


def rect(x, y, w, h, t, *, fill=None, stroke="line", rx=6, width=1) -> str:
    f = t[fill] if fill else "none"
    s = t[stroke] if stroke else "none"
    return (f'  <rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" '
            f'fill="{f}" stroke="{s}" stroke-width="{width}"/>\n')


# --------------------------------------------------------------------- hero

# The portfolio mark, straight out of portfolio-website/src/app/icon.svg: a
# diamond with a vertical slot cut through it, drawn with fill-rule evenodd.
MARK = ("M 128 30 L 226 128 L 128 226 L 30 128 Z "
        "M 108 70 L 148 70 L 148 186 L 108 186 Z")


def hero(t) -> str:
    """Animated mark on the left, name on the right.

    CSS keyframes, not SMIL and not JS: an <img>-loaded SVG runs no script.
    Opacity carries the animation and the transform only adds to it, so the
    mark is still legible wherever SVG transforms are ignored.
    """
    panel = 300
    css = (
        ".mk{transform-box:fill-box;transform-origin:center;"
        "animation:rise 6s ease-in-out infinite}"
        "@keyframes rise{0%{opacity:.18;transform:scale(.90) rotate(-8deg)}"
        "20%{opacity:1;transform:scale(1) rotate(0)}"
        "82%{opacity:1;transform:scale(1) rotate(0)}"
        "100%{opacity:.18;transform:scale(.90) rotate(-8deg)}}"
        ".rg{transform-box:fill-box;transform-origin:center;"
        "animation:ring 6s ease-out infinite}"
        "@keyframes ring{0%{opacity:.5;transform:scale(.55)}"
        "55%{opacity:0;transform:scale(1.25)}100%{opacity:0;transform:scale(1.25)}}"
        "@media(prefers-reduced-motion:reduce){.mk,.rg{animation:none}"
        ".mk{opacity:1}.rg{opacity:0}}"
    )
    b = f'  <style>{css}</style>\n'
    b += rect(0, 0, panel, panel, t, fill="wash", rx=8)
    cx = panel / 2
    b += (f'  <circle class="rg" cx="{cx}" cy="150" r="104" fill="none" '
          f'stroke="{t["accent"]}" stroke-width="1.5"/>\n')
    b += (f'  <g class="mk" transform="translate({cx - 90} 60) scale(0.703)">'
          f'<path fill-rule="evenodd" fill="{t["mark"]}" d="{MARK}"/></g>\n')

    nx = panel + 44
    b += text(nx, 92, "ILHAM", size=62, weight=700, spacing=-1, t=t)
    b += text(nx, 156, "BINTANG", size=62, weight=200, spacing=-1, fill="muted", t=t)
    b += text(nx, 220, "SATRIA", size=62, weight=700, spacing=-1, t=t)
    b += rule(nx, 252, W, t)
    b += text(nx, 286, "Data · Machine Learning · Surabaya", size=22, fill="muted", t=t)
    return svg(panel, b)


def band(num, label, t) -> str:
    b = rect(0, 0, W, 56, t, fill="band", stroke=None, rx=4)
    b += text(22, 37, num, size=24, weight=700, fill="accent", font=MONO, t=t)
    b += text(76, 37, "—", size=24, fill="muted", font=MONO, t=t)
    b += text(112, 37, label, size=24, weight=500, font=MONO, spacing=1, t=t)
    return svg(56, b)


def whoami(t) -> str:
    b = text(0, 38, "AI Engineer intern di Ideola sejak Juli 2026.", size=26, t=t)
    b += text(0, 84, "Mengejar kenapa metode bekerja, bukan daftar tool yang memakainya.",
              size=24, fill="muted", t=t)
    return svg(108, b)


# --------------------------------------------------------------- FIG. 01 map

# Branch label, then the repositories under it. Only repositories that are
# public, non-empty and safe to show.
MAP = [
    ("DATA ENGINEERING", ["Medallion", "EventDriven-Streaming", "Ingestion", "AnalyticsEngineering"]),
    ("QUALITY", ["Data-Quality"]),
    ("MACHINE LEARNING", ["ara-26", "RNN", "Goal-Scorer", "HeartClass"]),
    ("FUNDAMENTALS", ["XOR-Multi-Layer-Perceptron", "MLP-Digits", "NN-Parameter"]),
    ("AGENTS & APPS", ["agent", "Kino", "Warungku", "Portofolio"]),
]


def system_map(t) -> str:
    b = text(0, 26, "SYSTEM MAP — SATU ALUR, DARI DATA MENTAH KE KEPUTUSAN",
             size=19, weight=700, font=MONO, spacing=1, t=t)
    b += text(W, 26, "FIG. 01", size=19, fill="muted", font=MONO, anchor="end", t=t)
    b += rule(0, 40, W, t)

    hub_y = 96
    b += rect(0, 64, 236, 64, t, fill="wash")
    b += text(18, 92, "YONOBENGKEL", size=20, weight=700, fill="accent", font=MONO, t=t)
    b += text(18, 116, "32 repositori publik", size=17, fill="muted", t=t)

    y = 168
    spine, tx = 118, 172
    # Monospace runs about 0.6em per character, so 17px over the 674px that is
    # left of the column is roughly 66 characters. Wrap at 58 and the longest
    # repository name still clears the edge.
    for label, repos in MAP:
        lines, cur = [], ""
        for r in repos:
            cand = f"{cur} · {r}" if cur else r
            if len(cand) > 58:
                lines.append(cur)
                cur = r
            else:
                cur = cand
        if cur:
            lines.append(cur)
        b += (f'  <path d="M{spine} {hub_y + 34} L{spine} {y - 14}" stroke="{t["line"]}" '
              f'stroke-width="1" fill="none" stroke-dasharray="3 4"/>\n')
        b += (f'  <path d="M{spine} {y - 14} L{spine + 44} {y - 14}" stroke="{t["line"]}" '
              f'stroke-width="1" fill="none" stroke-dasharray="3 4"/>\n')
        b += text(tx, y - 8, label, size=17, weight=700, fill="accent",
                  font=MONO, spacing=1, t=t)
        for i, ln in enumerate(lines):
            b += text(tx, y + 20 + i * 24, ln, size=17, fill="muted", font=MONO, t=t)
        y += 42 + 24 * len(lines)
    b += text(0, y + 6, "garis putus — data bergerak", size=16, fill="muted", font=MONO, t=t)
    return svg(y + 24, b)


# --------------------------------------------------------- FIG. 02 telemetry

# Counted from the GitHub API on 2026-10-18 over non-fork public repositories.
# Primary language only, which is what the API reports per repository.
LANGS = [("Jupyter Notebook", 15), ("Python", 10), ("TypeScript", 2),
         ("HTML", 2), ("lainnya", 2)]
YEARS = [("2025", 6), ("2026", 26)]
TOTAL_REPOS = 32


def telemetry(t) -> str:
    b = text(0, 26, "TELEMETRY — DIHITUNG, BUKAN DITAKSIR", size=19, weight=700,
             font=MONO, spacing=1, t=t)
    b += text(W, 26, "FIG. 02", size=19, fill="muted", font=MONO, anchor="end", t=t)
    b += rule(0, 40, W, t)

    b += text(0, 76, "BAHASA UTAMA PER REPOSITORI", size=16, weight=700, fill="muted",
              font=MONO, spacing=1, t=t)
    lx, bw, y = 200, 420, 104
    top = max(v for _, v in LANGS)
    for name, v in LANGS:
        b += text(0, y + 15, name, size=18, font=MONO, t=t)
        b += rect(lx, y, round(bw * v / top), 22, t, fill=None, stroke=None, rx=3)
        b += (f'  <rect x="{lx}" y="{y}" width="{round(bw * v / top)}" height="22" '
              f'rx="3" fill="{t["accent"]}" opacity="0.85"/>\n')
        b += text(lx + bw + 18, y + 17, str(v), size=18, weight=700, font=MONO, t=t)
        y += 34

    y += 18
    b += rule(0, y, W, t, dash="3 5")
    y += 34
    b += text(0, y, "REPOSITORI BARU PER TAHUN", size=16, weight=700, fill="muted",
              font=MONO, spacing=1, t=t)
    y += 28
    for name, v in YEARS:
        b += text(0, y + 15, name, size=18, font=MONO, t=t)
        b += (f'  <rect x="{lx}" y="{y}" width="{round(bw * v / 26)}" height="22" '
              f'rx="3" fill="{t["accent"]}" opacity="0.85"/>\n')
        b += text(lx + bw + 18, y + 17, str(v), size=18, weight=700, font=MONO, t=t)
        y += 34

    y += 22
    b += rect(0, y, W, 66, t, fill="wash")
    b += text(24, y + 42, f"{TOTAL_REPOS} repositori publik", size=20, weight=700,
              fill="accent", font=MONO, t=t)
    b += text(W - 24, y + 42, "fork tidak dihitung", size=17, fill="muted",
              font=MONO, anchor="end", t=t)
    return svg(y + 90, b)


def footer(t) -> str:
    b = rule(0, 1, W, t)
    b += text(0, 46, "Kerja Praktik · Januari–Juni 2027", size=23, fill="muted", t=t)
    b += text(W, 46, "ilhambintangporto.vercel.app", size=23, fill="accent",
              font=MONO, anchor="end", t=t)
    return svg(70, b)


VISUALS = {
    "hero": hero,
    "s01": lambda t: band("01", "whoami", t),
    "whoami": whoami,
    "s02": lambda t: band("02", "system map", t),
    "map": system_map,
    "s03": lambda t: band("03", "projects", t),
    "s04": lambda t: band("04", "stack & tools", t),
    "s05": lambda t: band("05", "telemetry", t),
    "telemetry": telemetry,
    "s06": lambda t: band("06", "contribution", t),
    "footer": footer,
}

# Superseded visuals. Removed on every run so the repo never ships an asset the
# README stopped referencing.
RETIRED = ("header", "method", "topsis", "work", "stack")


def main() -> None:
    for theme in THEMES:
        out = ROOT + ("/assets" if theme == "light" else "/assets/dark")
        os.makedirs(out, exist_ok=True)
        for name, fn in VISUALS.items():
            with open(os.path.join(out, f"{name}.svg"), "w", encoding="utf-8", newline="\n") as fh:
                fh.write(fn(THEMES[theme]))
        for name in RETIRED:
            stale = os.path.join(out, f"{name}.svg")
            if os.path.exists(stale):
                os.remove(stale)
    print(f"wrote {len(VISUALS) * 2} files into assets/ and assets/dark/")


if __name__ == "__main__":
    main()
